/* Path: static/css/style.css */
/* Purpose: Frontend styling */
/* Layer: frontend */

/* General Reset */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* Body Styling */
body {
  font-family: Arial, sans-serif;
  font-size: 16px;
  color: #333;
  background-color: #f9f9f9;
  line-height: 1.6;
}

/* Header Styling */
header {
  background: #4CAF50;
  color: #fff;
  padding: 10px 20px;
  text-align: center;
}

header h1 {
  font-size: 2rem;
  margin: 0;
}

/* Navigation Bar */
nav {
  background: #333;
  color: #fff;
}

nav ul {
  list-style: none;
  display: flex;
  justify-content: center;
}

nav ul li {
  margin: 0 10px;
}

nav ul li a {
  color: #fff;
  text-decoration: none;
  padding: 5px 10px;
}

nav ul li a:hover {
  background: #4CAF50;
  border-radius: 5px;
}

/* Main Content */
main {
  padding: 20px;
  background: #fff;
  margin: 20px auto;
  max-width: 1200px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

main h2 {
  font-size: 1.5rem;
  margin-bottom: 10px;
}

main p {
  margin-bottom: 10px;
}

/* Buttons */
button {
  background: #4CAF50;
  color: #fff;
  border: none;
  padding: 10px 20px;
  cursor: pointer;
  border-radius: 5px;
}

button:hover {
  background: #45a049;
}

/* Footer */
footer {
  background: #333;
  color: #fff;
  text-align: center;
  padding: 10px 20px;
  position: fixed;
  bottom: 0;
  width: 100%;
}

footer p {
  margin: 0;
}

